eIndex:{title:"AA-Omniscience Index",content:(0,a.jsx)("p",{children:o.u.omniscienceIndex})},aaOmniscienceIndexOutputTokens:{title:"AA-Omniscience Index Output Tokens",content:(0,a.jsx)("p",{children:"The number of output tokens required to answer all questions in the AA-Omniscience benchmark (including reasoning tokens)."})},aaSearchIndex:{title:"Artificial Analysis Search Index",content:(0,a.jsx)("p",{children:"The equal-weighted mean of each Search API provider's score on DeepSearchQA (average F1), BrowseComp (exact-answer accuracy), and AA-Omniscience (accuracy), shown on a 0-100 scale. Every result runs the same candidate answer model, harness, and settings. The only variable is the Search API provider."})},activeParametersAtInferenceTime:{title:"Active Parameters at Inference Time",content:(0,a.jsx)("p",{children:"The number of parameters actually executed during each inference forward pass, expressed in billions. For Mixture of Experts (MoE) models, a routing mechanism selects a subset of experts per token, resulting in fewer active than total parameters. Dense models use all parameters, so active equals total."})},aime25x32:{title:"AIME25x32",content:(0,a.jsxs)("p",{children:["Results on the ",(0,a.jsx)("span",{className:"font-semibold",children:"AIME 2025"})," benchmark, which tests advanced mathematical problem-solving capabilities. Each provider endpoint is evaluated in 32 independent runs."]})},artificialAnalysisAgenticIndex:{title:"Artificial Analysis Agentic Index",content:(0,a.jsxs)("p",{children:["Represents the average of agentic capabilities benchmarks in the Artificial Analysis Intelligence Index (",h.Z8.map(e=>e.shortName).join(", "),")."]})},artificialAnalysisIntelligenceIndex:{title:"Artificial Analysis Intelligence Index",content:(0,a.jsxs)("p",{children:[m.Fj," includes: ",h.Rm.map(e=>e.shortName).join(", "),". See"," ",(0,a.jsx)(I,{href:"/methodology/intelligence-benchmarking",children:"Intelligence Index methodology"})," ","for further details, including a breakdown of each evaluation and how we run them."]})},artificialAnalysisMultilingualIndex:{title:"Artificial Analysis Multilingual Index",content:(0,a.jsxs)("p",{children:["An index assessing multilingual performance in general reasoning across multiple languages. Results are computed across"," ",Object.values(c.KM).map(e=>{let{label:t}=e;return t}).join(", "),". See"," ",(0,a.jsx)(I,{href:"/methodology/intelligence-benchmarking",children:"Multilingual Intelligence Index methodology"})," ","for further details."]})},artificialAnalysisSearchIndexVsSearchLatencyPerTask:{title:"Artificial Analysis Search Index vs. Search Latency per Task",content:(0,a.jsx)("p",{children:"Search quality against the measured search time per benchmark task, across search providers only. The Pareto frontier joins the providers no other provider beats on both quality and search latency."})},artificialAnalysisSpeechToSpeechIndex:{title:"Artificial Analysis Speech to Speech Index",content:(0,a.jsx)("p",{children:"Weighted average score for native audio models across Speech Reasoning (Big Bench Audio), Conversational Dynamics (Full Duplex Bench), and Agentic Performance (\uD835\uDF0F-Voice). Models must have results for all three datasets to receive an index score."})},artificialAnalysisSpeechToSpeechIndexWithArena:{title:"Artificial Analysis Speech to Speech Index",content:(0,a.jsxs)("div",{className:"space-y-2",children:[(0,a.jsx)("p",{children:"Equal-weighted score across Speech Reasoning (Big Bench Audio), Agentic Performance (\uD835\uDF0F-Voice), Arena Preference (Arena Score), and Task Success Rate. Models must have results for all four components to receive an index score."}),(0,a.jsx)("p",{children:"Preference Elo is converted into expected preference against an 800-Elo baseline: Arena Score = 100 / (1 + 10^((800 − frozen Elo) / 400)). The rating is frozen when a model first becomes eligible for publication, so it does not track the live Elo shown on the Arena charts."})]})},artificialAnalysisWordErrorRateAaWerIndex:{title:"Artificial Analysis Word Error Rate (AA-WER) Index",content:(0,a.jsxs)("div",{className:"space-y-2",children:[(0,a.jsx)("p",{children:"Measures transcription accuracy across 3 datasets to evaluate models in real-world speech with diverse accents, domain-specific language, and challenging channel & acoustic conditions."}),(0,a.jsxs)("p",{children:["AA-WER is calculated as an audio-duration-weighted average of WER across ~8 hours from three datasets: AA-AgentTalk (50%), VoxPopuli-Cleaned-AA (25%), and Earnings22-Cleaned-AA (25%). See"," ",(0,a.jsx)(I,{href:"/methodology/speech-to-text",children:"methodology"})," for more detail."]})]})},artificialAnalysisWordErrorRateAaWerStreamingIndex:{title:"Artificial Analysis Word Error Rate (AA-WER) Streaming Index",content:(0,a.jsxs)("div",{className:"space-y-2",children:[(0,a.jsx)("p",{children:"Measures transcription accuracy of models where audio is streamed in real-time, chunk by chunk, as opposed to batch transcription, where the full audio file is submitted all at once."}),(0,a.jsx)("p",{children:"AA-WER Streaming consists of around 8 hours of audio from three datasets: AA-AgentTalk (50%), VoxPopuli (25%), and Earnings22 (25%). The datasets cover real-world speech with diverse accents, domain-specific language, and challenging acoustic conditions."}),(0,a.jsx)("p",{children:"AA-WER Streaming Index is a dataset-weighted average consistent with our offline STT benchmark: AA-AgentTalk 50% / VoxPopuli 25% / Earnings22 25%. WER is audio-duration-weighted within each dataset; Time to Final and Time to First Partial are simple averages within each dataset, then dataset-weighted 50% / 25% / 25% overall."})]})},attemptRate:{title:"Attempt Rate",content:(0,a.jsx)("p",{children:'The proportion of questions that the model attempted to answer, rather than abstaining or saying "I don\'t know". Attempt rate is an indicator of the model’s confidence in its embedded knowledge.'})},